//! Support for `ws_fmt!`: builds a string template from the macro's pieces.

use crate::expr::Expr;
use crate::ir::{self, ExprKind, StrExpr, StrModifier, StrToken};
use crate::ty::{Any, Str};

/// A piece of a template, as generated by `ws_fmt!`.
#[doc(hidden)]
#[derive(Clone, Copy, Debug)]
pub enum Piece {
    /// Literal text.
    Text(&'static str),
    /// A reference to the argument with this index.
    Arg(usize),
}

/// Builds the template `Expr<Str>` for `ws_fmt!`.
#[doc(hidden)]
#[track_caller]
#[must_use]
pub fn template(pieces: &[Piece], args: Vec<Expr<Any>>) -> Expr<Str> {
    let mut tokens = Vec::new();
    for piece in pieces {
        match *piece {
            Piece::Text(text) => push_text(&mut tokens, text),
            Piece::Arg(i) => tokens.push(StrToken::Arg(i)),
        }
    }
    let args = args.into_iter().map(Expr::into_ir).collect();
    Expr::from_ir(ir::Expr::here(ExprKind::Str(StrExpr::Custom {
        tokens,
        args,
    })))
}

impl Expr<Str> {
    /// Maps the text to fullwidth characters (placeholders and tags are untouched).
    ///
    /// Only string templates (literals and `ws_fmt!`) can be modified; anything else is an error.
    #[track_caller]
    #[must_use]
    pub fn fullwidth(self) -> Self {
        self.modified(StrModifier::Fullwidth)
    }

    /// Forces the large Blizzard Global font by swapping the first suitable character for a
    /// lookalike; an error when the text has none.
    #[track_caller]
    #[must_use]
    pub fn big(self) -> Self {
        self.modified(StrModifier::Big)
    }

    /// Keeps lowercase Latin letters lowercase, using lookalike characters.
    #[track_caller]
    #[must_use]
    pub fn case_sensitive(self) -> Self {
        self.modified(StrModifier::CaseSensitive)
    }

    #[track_caller]
    fn modified(self, modifier: StrModifier) -> Self {
        Self::from_ir(ir::Expr::here(ExprKind::StrModify {
            modifier,
            inner: self.into_ir(),
        }))
    }
}

/// Appends literal text: carriage returns are dropped and adjacent text is merged.
pub(crate) fn push_text(tokens: &mut Vec<StrToken>, text: &str) {
    let text = text.replace('\r', "");
    if text.is_empty() {
        return;
    }
    match tokens.last_mut() {
        Some(StrToken::Text(prev)) => prev.push_str(&text),
        _ => tokens.push(StrToken::Text(text)),
    }
}

/// Appends text that is already part of a template: it keeps every character (a carriage
/// return can be a digit of generated text) and merges with the text before it.
pub(crate) fn merge_text(tokens: &mut Vec<StrToken>, text: &str) {
    if text.is_empty() {
        return;
    }
    match tokens.last_mut() {
        Some(StrToken::Text(prev)) => prev.push_str(text),
        _ => tokens.push(StrToken::Text(text.to_owned())),
    }
}

